function secondsToRemoveOccurrences(s) {
  const chars = s.split('');
  let seconds = 0;
  let changed = true;

  while (changed) {
    changed = false;
    for (let i = 0; i + 1 < chars.length; i++) {
      if (chars[i] === '0' && chars[i + 1] === '1') {
        chars[i] = '1';
        chars[i + 1] = '0';
        changed = true;
        i++;
      }
    }
    if (changed) {
      seconds++;
    }
  }
  return seconds;
}

