function secondsToRemoveOccurrences(s) {
  // "01" matches can never overlap, so a global regex replace performs one simultaneous second.
  let count = 0;
  while (s.includes('01')) {
    s = s.replace(/01/g, '10');
    count++;
  }
  return count;
}

