function generate(rand, size) {
  const n = size === 'large' ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 10);
  const shape = rand();
  let s = '';
  if (shape < 0.25) {
    const zeros = Math.floor(rand() * (n + 1));
    s = '0'.repeat(zeros) + '1'.repeat(n - zeros);
  } else {
    const ones = 0.1 + rand() * 0.8;
    for (let i = 0; i < n; i++) s += rand() < ones ? '1' : '0';
  }
  return [s];
}
